const allItems = items;

const cleanItems = [];
const baseUrl = "https://unlistedzone.com";

for (const item of allItems) {
  const rawLink = item.json.link || "";
  const rawTitle = item.json.title_raw || "";

  if (rawTitle.trim() === "") {
    continue;
  }

  const title = rawTitle.trim();

  if (title.toLowerCase().includes("ncdex")) {
    continue;
  }

  // 🔹 FIXED: Safely convert to string before using startsWith
  let link = String(rawLink || "").trim();

  if (link !== "" && !link.startsWith("http")) {
    link = baseUrl + link;
  }

  cleanItems.push({
    json: {
      title: title,
      link: link,
    },
  });
}

return cleanItems.slice(0, 2);

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {// Get data from the Gainers node
// Replace 'Google Sheets Gainers' with the EXACT name of your gainers node
const gainers = $('get sheet gainers').all().map(item => item.json);

// Get data from the Losers node
// Replace 'Google Sheets Losers' with the EXACT name of your losers node
const losers = $('get sheet losers').all().map(item => item.json);

// Return them as a single combined object
return {
  json: {
    gainers_list: gainers,
    losers_list: losers
  }
};
  item.json.myNewField = 1;
}

return $input.all();

// 1. Get the JSON data automatically from the previous node
const json = $input.item.json;

// 2. Extract the text using the specific path for Gemini
// Path: content -> parts -> [0] -> text
let text;

try {
  text = json.content.parts[0].text;
} catch (error) {
  // If the path fails, try finding standard output fields
  text = json.output || json.text;
}

// 3. Safety Check: Stop if text is missing
if (!text || typeof text !== 'string') {
  throw new Error("Text not found. Incoming data: " + JSON.stringify(json));
}

// 4. Split the text into Gainers and Losers sections
const parts = text.split(/SECTION 2: LOSERS/i);

const gainers = parts[0] ? parts[0].replace(/SECTION 1: GAINERS/i, "").trim() : "No Gainers";
const losers = parts[1] ? parts[1].trim() : "No Losers";

// 5. Return the clean results
return {
  json: {
    gainers_clean: gainers,
    losers_clean: losers
  }
};

