// 1. Get the raw text from Gemini
// Handle different output paths (output, text, or message.content)
const json = $input.item.json;
const rawContent = json.output || json.text || json.message?.content || json.content?.parts?.[0]?.text;

if (!rawContent) {
  throw new Error("No content found in AI response.");
}

// 2. Sanitize the output (Remove markdown ```json fences if AI adds them)
const cleanJsonString = rawContent.replace(/```json/g, "").replace(/```/g, "").trim();

// 3. Parse the JSON
let captions;
try {
  captions = JSON.parse(cleanJsonString);
} catch (e) {
  throw new Error("AI output was not valid JSON. Output: " + rawContent);
}

// 4. Return clear variables for the next node
return {
  json: {
    linkedin_final: captions.linkedin,
    facebook_final: captions.facebook,
    instagram_final: captions.instagram,
    twitter_final: captions.twitter
  }
};

// 1. Get raw text
const rawContent = $input.item.json.content.parts[0].text;

// 2. Extract JSON payload between outer braces
const jsonMatch = rawContent.match(/\{[\s\S]*\}/);

if (!jsonMatch) {
  throw new Error("No JSON object found in LLM output");
}

let cleanJsonString = jsonMatch[0];

// 3. Parse JSON
try {
  const data = JSON.parse(cleanJsonString);
  return [{ json: data }];
} catch (e) {
  // Helpful log to see the exact invalid slice in execution logs
  console.log("Failed JSON payload around error:", cleanJsonString.slice(4500, 4700));
  throw new Error(`AI output was not valid JSON: ${e.message}`);
}

